#include <windows.h>

int main() {
    HMODULE user32 = LoadLibraryW(L"user32.dll");
    if (user32 == nullptr) {
        return static_cast<int>(GetLastError());
    }

    using MessageBoxW_t = int (WINAPI*)(HWND, LPCWSTR, LPCWSTR, UINT);
    auto messageBoxW = reinterpret_cast<MessageBoxW_t>(
        GetProcAddress(user32, "MessageBoxW"));
    if (messageBoxW != nullptr) {
        messageBoxW(nullptr, L"Loaded from user32.dll", L"LoadLibraryW", MB_OK);
    }

    FreeLibrary(user32);
    return 0;
}

