#include <windows.h>
#include <stdio.h>

int main() {
    HMODULE module = GetModuleHandleA(nullptr);
    HRSRC resource = FindResourceA(module, MAKEINTRESOURCEA(1), RT_VERSION);
    if (resource == nullptr) {
        printf("No version resource in this image.\n");
        return 0;
    }

    DWORD size = SizeOfResource(module, resource);
    HGLOBAL loaded = LoadResource(module, resource);
    if (loaded != nullptr) {
        const void* data = LockResource(loaded);
        printf("Version resource: %lu bytes at %p\n", size, data);
    }
    return 0;
}

